# Load the project's functions straight from the checkout with pkgload; the
# repo is never installed (decision 0042). The site build sets CFB2NFL_ROOT,
# a local render finds the checkout from the working directory.
root <- Sys.getenv("CFB2NFL_ROOT")
if (!nzchar(root)) root <- pkgload::pkg_path()
knitr::opts_knit$set(root.dir = root)
pkgload::load_all(root, quiet = TRUE)
library(dplyr)
library(purrr)
library(htmltools)
library(reactable)

rd_files <- sort(list.files(file.path(root, "man"), pattern = "\\.Rd$", full.names = TRUE))

# Title from the \title{} section; internal functions (altdoc skips them) omitted.
fn_meta <- map_dfr(rd_files, function(f) {
  raw <- readLines(f, warn = FALSE)
  if (any(grepl("\\\\internal", raw))) {
    return(NULL)
  }
  name <- tools::file_path_sans_ext(basename(f))
  title <- tryCatch(
    paste(unlist(tools:::.Rd_get_metadata(raw, "title")), collapse = " "),
    error = function(e) name
  )
  tibble(
    fn = name,
    title = ifelse(nzchar(title), title, name),
    link = paste0("../man/", name, ".html")
  )
})
